# Compare ring model metrics on demo4: geometric distance by square erosion from each 4-connected non-wall component
# current state already has parsed in4/out4 and component 4-connectivity arrays from prior analysis
# compute 8-neighbor boundary depth within component
H4,W4=in4.shape

def depth_by_neighbors(lab, comps, wall, diagonals=True):
    h,w=lab.shape; dep=np.full((h,w),-1,int)
    dirs=[(dy,dx) for dy in (-1,0,1) for dx in (-1,0,1) if (dy or dx) and (diagonals or abs(dy)+abs(dx)==1)]
    for k,cells in enumerate(comps):
        q=deque()
        for r,c in cells:
            if any(not(0<=r+dy<h and 0<=c+dx<w) or lab[r+dy,c+dx]!=k for dy,dx in dirs):
                dep[r,c]=0;q.append((r,c))
        while q:
            r,c=q.popleft()
            for dy,dx in dirs:
                rr,cc=r+dy,c+dx
                if 0<=rr<h and 0<=cc<w and lab[rr,cc]==k and dep[rr,cc]<0:
                    dep[rr,cc]=dep[r,c]+1;q.append((rr,cc))
    return dep
# note 8-neighbor distance within components (not wall distance)
dep8=depth_by_neighbors(lab4,cs4,8,True)
for k,cs in enumerate(cs4):
    seeds=[(r,c,int(in4[r,c]),int(dep8[r,c])) for r,c in cs if in4[r,c] not in (7,8)]
    if seeds:
        by=defaultdict(set)
        for r,c in cs:by[int(dep8[r,c])].add(int(out4[r,c]))
        print(k,seeds,'layers',dict(by))

